item.command:
/bin/bash -lc "python - <<'PY'
import os
for root, dirs, files in os.walk('/opt/menagerie/unitree_h1'):
    for f in files:
        if f.endswith(('.xml','.py','.md','.txt','.yaml','.yml')):
            p=os.path.join(root,f)
            if 'scene' in f or 'h1' in p.lower() or 'walk' in p.lower() or 'controller' in p.lower():
                print(p)
PY"

